insert into public.podcast_episodes (slug, number, minutes, title_he, guest_he, description_he, points_he, cover_path, cover_alt, video_url, audio_path, published_on, i18n, status, sort_order) values
  ('ep-1', 1, 34, 'החלום הראשון: איך מתחילים לבנות בית', 'אורח: מנהל פרויקטים, GAD MIVNIM', 'שיחה פתוחה על הצעדים הראשונים – מהמגרש ועד התוכנית, ואיך לא ללכת לאיבוד בדרך.', array['בדיקת זכויות בנייה', 'בחירת צוות תכנון', 'לוח זמנים ריאלי']::text[], null, null, null, null, null, '{"en":{"title":"The first dream: how to start building a home","guest":"Guest: Project manager, GAD MIVNIM","desc":"An open conversation about the first steps – from the plot to the plan, and how not to get lost along the way.","points":["Checking building rights","Choosing a design team","A realistic timeline"]},"ru":{"title":"Первая мечта: с чего начать строительство дома","guest":"Гость: руководитель проектов, GAD MIVNIM","desc":"Откровенный разговор о первых шагах — от участка до проекта и о том, как не заблудиться в пути.","points":["Проверка прав на застройку","Выбор проектной команды","Реалистичный график"]},"fr":{"title":"Le premier rêve : comment commencer à construire sa maison","guest":"Invité : chef de projet, GAD MIVNIM","desc":"Une conversation ouverte sur les premiers pas – du terrain au plan, et comment ne pas se perdre en route.","points":["Vérifier les droits à construire","Choisir l’équipe de conception","Un calendrier réaliste"]}}'::jsonb, 'published', 1),
  ('ep-2', 2, 28, 'שיפוץ בלי כאב ראש', 'אורח: מנהל עבודה', 'מה באמת קורה באתר שיפוץ, ואיך שומרים על לוח זמנים ותקציב.', array['הכנה לפני השיפוץ', 'הפתעות נפוצות ואיך נמנעים', 'עבודה מול השכנים']::text[], null, null, null, null, null, '{"en":{"title":"Renovation without the headache","guest":"Guest: Site manager","desc":"What really happens on a renovation site, and how to stay on schedule and on budget.","points":["Preparing before the renovation","Common surprises and how to avoid them","Working with the neighbors"]},"ru":{"title":"Ремонт без головной боли","guest":"Гость: прораб","desc":"Что на самом деле происходит на ремонте и как уложиться в сроки и бюджет.","points":["Подготовка до ремонта","Частые сюрпризы и как их избежать","Отношения с соседями"]},"fr":{"title":"Rénover sans prise de tête","guest":"Invité : chef de chantier","desc":"Ce qui se passe vraiment sur un chantier de rénovation, et comment tenir les délais et le budget.","points":["Se préparer avant les travaux","Les surprises fréquentes et comment les éviter","Composer avec les voisins"]}}'::jsonb, 'published', 2),
  ('ep-3', 3, 41, 'תמ"א 38 ופינוי בינוי – מה הדיירים צריכים לדעת', 'אורחת: יועצת התחדשות עירונית', 'התחדשות עירונית מנקודת המבט של הדיירים – זכויות, תהליכים ושקיפות.', array['שלבי הפרויקט', 'נציגות דיירים', 'ליווי משפטי']::text[], null, null, null, null, null, '{"en":{"title":"TAMA 38 and urban renewal – what residents need to know","guest":"Guest: Urban renewal consultant","desc":"Urban renewal from the residents’ point of view – rights, processes and transparency.","points":["Project stages","Residents’ committee","Legal guidance"]},"ru":{"title":"ТАМА 38 и «снос-строительство» — что нужно знать жильцам","guest":"Гостья: консультант по городскому обновлению","desc":"Городское обновление глазами жильцов — права, процессы и прозрачность.","points":["Этапы проекта","Представительство жильцов","Юридическое сопровождение"]},"fr":{"title":"TAMA 38 et renouvellement urbain – ce que les résidents doivent savoir","guest":"Invitée : consultante en renouvellement urbain","desc":"Le renouvellement urbain du point de vue des résidents – droits, démarches et transparence.","points":["Les étapes du projet","La représentation des résidents","L’accompagnement juridique"]}}'::jsonb, 'published', 3),
  ('ep-4', 4, 25, 'מטבח שהוא הלב של הבית', 'אורחת: מעצבת פנים', 'איך מתכננים מטבח יפה, נוח ופרקטי – מהסקיצה ועד ההתקנה.', array['תכנון משולש העבודה', 'בחירת משטחים', 'תאורה במטבח']::text[], null, null, null, null, null, '{"en":{"title":"A kitchen that is the heart of the home","guest":"Guest: Interior designer","desc":"How to plan a beautiful, comfortable and practical kitchen – from sketch to installation.","points":["Planning the work triangle","Choosing countertops","Kitchen lighting"]},"ru":{"title":"Кухня — сердце дома","guest":"Гостья: дизайнер интерьера","desc":"Как спланировать красивую, удобную и практичную кухню — от эскиза до монтажа.","points":["Планирование рабочего треугольника","Выбор столешниц","Освещение кухни"]},"fr":{"title":"Une cuisine au cœur de la maison","guest":"Invitée : architecte d’intérieur","desc":"Comment concevoir une cuisine belle, confortable et pratique – de l’esquisse à l’installation.","points":["Planifier le triangle d’activité","Choisir les plans de travail","L’éclairage de la cuisine"]}}'::jsonb, 'published', 4),
  ('ep-5', 5, 30, 'רטיבות: האויב השקט של המבנה', 'אורח: מומחה איטום', 'מאיפה מגיעה הרטיבות, איך מזהים אותה מוקדם ואיך מטפלים בה פעם אחת ולתמיד.', array['סימני אזהרה', 'איטום גגות ומרפסות', 'בדיקת הצפה']::text[], null, null, null, null, null, '{"en":{"title":"Damp: the building’s silent enemy","guest":"Guest: Waterproofing expert","desc":"Where damp comes from, how to spot it early and how to deal with it once and for all.","points":["Warning signs","Waterproofing roofs and balconies","Flood testing"]},"ru":{"title":"Сырость: тихий враг здания","guest":"Гость: эксперт по гидроизоляции","desc":"Откуда берётся сырость, как распознать её вовремя и устранить раз и навсегда.","points":["Тревожные признаки","Гидроизоляция крыш и балконов","Проверка заливом"]},"fr":{"title":"L’humidité : l’ennemi silencieux du bâtiment","guest":"Invité : expert en étanchéité","desc":"D’où vient l’humidité, comment la repérer tôt et la traiter une fois pour toutes.","points":["Les signes d’alerte","L’étanchéité des toits et des balcons","Le test d’inondation"]}}'::jsonb, 'published', 5),
  ('ep-6', 6, 37, 'שיקום מבנים ישנים – לשמור על הנשמה', 'אורח: מהנדס קונסטרוקציה', 'איך מחזירים חיים למבנה ותיק בלי לאבד את האופי שלו.', array['סקר הנדסי', 'חיזוק שלד', 'מבנים לשימור']::text[], null, null, null, null, null, '{"en":{"title":"Restoring old buildings – keeping their soul","guest":"Guest: Structural engineer","desc":"How to bring an old building back to life without losing its character.","points":["Engineering survey","Structural reinforcement","Heritage buildings"]},"ru":{"title":"Реставрация старых зданий — сохранить душу","guest":"Гость: инженер-конструктор","desc":"Как вернуть к жизни старое здание, не потеряв его характер.","points":["Инженерное обследование","Усиление каркаса","Здания под охраной"]},"fr":{"title":"Restaurer les bâtiments anciens – préserver leur âme","guest":"Invité : ingénieur en structure","desc":"Comment redonner vie à un bâtiment ancien sans perdre son caractère.","points":["L’expertise technique","Le renforcement de la structure","Les bâtiments classés"]}}'::jsonb, 'published', 6),
  ('ep-7', 7, 22, 'בטיחות באתר – לפני הכל', 'אורח: ממונה בטיחות', 'מה עושים כדי שכל יום עבודה באתר יסתיים בשלום.', array['עבודה בגובה', 'גידור ושילוט', 'מצלמות 24/7']::text[], null, null, null, null, null, '{"en":{"title":"Site safety – first of all","guest":"Guest: Safety officer","desc":"What it takes for every working day on site to end safely.","points":["Working at height","Fencing and signage","24/7 cameras"]},"ru":{"title":"Безопасность на площадке — прежде всего","guest":"Гость: специалист по охране труда","desc":"Что нужно, чтобы каждый рабочий день на площадке заканчивался благополучно.","points":["Работы на высоте","Ограждение и знаки","Камеры 24/7"]},"fr":{"title":"La sécurité sur le chantier – avant tout","guest":"Invité : responsable sécurité","desc":"Ce qu’il faut pour que chaque journée de chantier se termine sans incident.","points":["Le travail en hauteur","Clôtures et signalisation","Caméras 24h/24"]}}'::jsonb, 'published', 7),
  ('ep-8', 8, 29, 'איך בוחרים קבלן שאפשר לסמוך עליו', 'אורח: מנהל פרויקטים, GAD MIVNIM', 'השאלות הנכונות, הבדיקות שחייבים לעשות והנורות האדומות.', array['רישיון וביטוח', 'חוזה ומפרט', 'תקשורת שוטפת']::text[], null, null, null, null, null, '{"en":{"title":"How to choose a contractor you can trust","guest":"Guest: Project manager, GAD MIVNIM","desc":"The right questions, the must-do checks and the red flags.","points":["License and insurance","Contract and specification","Ongoing communication"]},"ru":{"title":"Как выбрать подрядчика, которому можно доверять","guest":"Гость: руководитель проектов, GAD MIVNIM","desc":"Правильные вопросы, обязательные проверки и тревожные сигналы.","points":["Лицензия и страховка","Договор и спецификация","Постоянная связь"]},"fr":{"title":"Comment choisir un entrepreneur de confiance","guest":"Invité : chef de projet, GAD MIVNIM","desc":"Les bonnes questions, les vérifications indispensables et les signaux d’alarme.","points":["Licence et assurance","Contrat et cahier des charges","Une communication suivie"]}}'::jsonb, 'published', 8),
  ('ep-9', 9, 24, 'תאורה שמשנה את הבית', 'אורחת: מעצבת תאורה', 'איך אור נכון יוצר אווירה, נוחות וחיסכון.', array['שכבות תאורה', 'גוונים וטמפרטורת צבע', 'תאורת חוץ']::text[], null, null, null, null, null, '{"en":{"title":"Lighting that transforms the home","guest":"Guest: Lighting designer","desc":"How the right light creates atmosphere, comfort and savings.","points":["Layers of lighting","Tones and color temperature","Outdoor lighting"]},"ru":{"title":"Освещение, которое меняет дом","guest":"Гостья: дизайнер освещения","desc":"Как правильный свет создаёт атмосферу, комфорт и экономию.","points":["Слои освещения","Оттенки и цветовая температура","Наружное освещение"]},"fr":{"title":"Un éclairage qui transforme la maison","guest":"Invitée : conceptrice lumière","desc":"Comment une bonne lumière crée ambiance, confort et économies.","points":["Les couches d’éclairage","Teintes et température de couleur","L’éclairage extérieur"]}}'::jsonb, 'published', 9),
  ('ep-10', 10, 26, 'אחרי המסירה: בדק בית ואחריות', 'אורח: מנהל שירות לקוחות', 'מה קורה אחרי שמקבלים את המפתח, ולמה שירות טוב לא נגמר במסירה.', array['תעודת אחריות', 'בדק בית', 'מנויי אחזקה']::text[], null, null, null, null, null, '{"en":{"title":"After handover: defects period and warranty","guest":"Guest: Customer service manager","desc":"What happens after you get the key, and why good service doesn’t end at handover.","points":["Warranty certificate","Defects liability period","Maintenance plans"]},"ru":{"title":"После сдачи: гарантийный период и обязательства","guest":"Гость: руководитель клиентского сервиса","desc":"Что происходит после получения ключей и почему хороший сервис не заканчивается сдачей.","points":["Гарантийный сертификат","Гарантийный период","Абонементы на обслуживание"]},"fr":{"title":"Après la livraison : garantie et parfait achèvement","guest":"Invité : responsable du service client","desc":"Ce qui se passe après la remise des clés, et pourquoi un bon service ne s’arrête pas à la livraison.","points":["Le certificat de garantie","La garantie de parfait achèvement","Les contrats d’entretien"]}}'::jsonb, 'published', 10),
  ('ep-11', 11, 31, 'תכנון נכון, חיסכון מוכח', 'אורח: אדריכל', 'למה שעה של תכנון חוסכת שבוע של תיקונים – ואיך עושים את זה נכון.', array['תיאום בין אנשי המקצוע', 'תוכניות עבודה מפורטות', 'ניהול שינויים']::text[], null, null, null, null, null, '{"en":{"title":"Right planning, proven savings","guest":"Guest: Architect","desc":"Why an hour of planning saves a week of repairs – and how to do it right.","points":["Coordination between professionals","Detailed working drawings","Managing changes"]},"ru":{"title":"Правильное планирование — доказанная экономия","guest":"Гость: архитектор","desc":"Почему час планирования экономит неделю исправлений — и как сделать это правильно.","points":["Координация специалистов","Подробные рабочие чертежи","Управление изменениями"]},"fr":{"title":"Bonne planification, économies prouvées","guest":"Invité : architecte","desc":"Pourquoi une heure de planification épargne une semaine de réparations – et comment bien s’y prendre.","points":["La coordination entre les professionnels","Des plans d’exécution détaillés","La gestion des modifications"]}}'::jsonb, 'published', 11),
  ('ep-12', 12, 27, 'עיצוב פנים: מהחלום להדמיה', 'אורחת: מעצבת פנים', 'איך הופכים רעיון לעיצוב מדויק – ורואים אותו לפני שמשקיעים.', array['קונספט וסגנון', 'הדמיות תלת-ממד', 'בחירת חומרים וצבעים']::text[], null, null, null, null, null, '{"en":{"title":"Interior design: from dream to visualization","guest":"Guest: Interior designer","desc":"How to turn an idea into a precise design – and see it before you invest.","points":["Concept and style","3D visualizations","Choosing materials and colors"]},"ru":{"title":"Дизайн интерьера: от мечты к визуализации","guest":"Гостья: дизайнер интерьера","desc":"Как превратить идею в точный дизайн — и увидеть его до вложений.","points":["Концепция и стиль","3D-визуализации","Выбор материалов и цветов"]},"fr":{"title":"Architecture d’intérieur : du rêve à la visualisation","guest":"Invitée : architecte d’intérieur","desc":"Comment transformer une idée en un design précis – et le voir avant d’investir.","points":["Concept et style","Les visualisations 3D","Le choix des matériaux et des couleurs"]}}'::jsonb, 'published', 12),
  ('ep-13', 13, 29, 'בית חכם: הטכנולוגיה שנכנסת לקירות', 'אורח: מתכנן מערכות חשמל ותקשורת', 'אילו מערכות חכמות שווה לתכנן כבר היום, ואיך מכינים תשתית לעתיד.', array['תאורה ותריסים חכמים', 'מצלמות ואבטחה', 'עמדת טעינה לרכב']::text[], null, null, null, null, null, '{"en":{"title":"Smart home: the technology inside the walls","guest":"Guest: Electrical and communications designer","desc":"Which smart systems are worth planning today, and how to prepare infrastructure for the future.","points":["Smart lighting and shutters","Cameras and security","EV charging point"]},"ru":{"title":"Умный дом: технологии в стенах","guest":"Гость: проектировщик электрики и слаботочных систем","desc":"Какие умные системы стоит заложить уже сегодня и как подготовить инфраструктуру на будущее.","points":["Умное освещение и жалюзи","Камеры и охрана","Зарядная станция для автомобиля"]},"fr":{"title":"Maison connectée : la technologie dans les murs","guest":"Invité : concepteur en électricité et réseaux","desc":"Quels systèmes intelligents prévoir dès aujourd’hui, et comment préparer l’infrastructure pour l’avenir.","points":["Éclairage et volets connectés","Caméras et sécurité","Borne de recharge pour véhicule"]}}'::jsonb, 'published', 13),
  ('ep-14', 14, 23, 'אינסטלציה: מה שמתחת לרצפה', 'אורח: אינסטלטור מוסמך', 'צנרת, ביוב וניקוז – החלק שלא רואים אבל מרגישים כשהוא לא עובד.', array['החלפת צנרת ישנה', 'שיפועים וניקוז', 'איתור נזילות']::text[], null, null, null, null, null, '{"en":{"title":"Plumbing: what lies beneath the floor","guest":"Guest: Licensed plumber","desc":"Pipes, sewage and drainage – the part you don’t see but feel when it fails.","points":["Replacing old pipes","Slopes and drainage","Leak detection"]},"ru":{"title":"Сантехника: что скрыто под полом","guest":"Гость: лицензированный сантехник","desc":"Трубы, канализация и дренаж — то, чего не видно, но что сразу чувствуется, когда не работает.","points":["Замена старых труб","Уклоны и дренаж","Поиск протечек"]},"fr":{"title":"Plomberie : ce qui se cache sous le sol","guest":"Invité : plombier agréé","desc":"Tuyauterie, égouts et drainage – la partie qu’on ne voit pas mais qu’on ressent quand elle lâche.","points":["Remplacer les anciennes canalisations","Pentes et drainage","La détection des fuites"]}}'::jsonb, 'published', 14),
  ('ep-15', 15, 25, 'גינה שמזמינה הביתה', 'אורחת: מתכננת נוף', 'איך מתכננים חוץ ירוק, חסכוני במים ונעים לאורך כל השנה.', array['בחירת צמחייה', 'מערכת השקיה חכמה', 'תאורת גן']::text[], null, null, null, null, null, '{"en":{"title":"A garden that welcomes you home","guest":"Guest: Landscape designer","desc":"How to plan a green, water-saving outdoor space that’s pleasant all year round.","points":["Choosing plants","Smart irrigation system","Garden lighting"]},"ru":{"title":"Сад, который зовёт домой","guest":"Гостья: ландшафтный дизайнер","desc":"Как спланировать зелёную территорию, экономную в поливе и приятную круглый год.","points":["Выбор растений","Умная система полива","Садовое освещение"]},"fr":{"title":"Un jardin qui invite à rentrer","guest":"Invitée : paysagiste","desc":"Comment concevoir un extérieur vert, économe en eau et agréable toute l’année.","points":["Le choix des plantes","Un arrosage intelligent","L’éclairage du jardin"]}}'::jsonb, 'published', 15),
  ('ep-16', 16, 26, 'ריצוף וחיפויים: לבחור פעם אחת ונכון', 'אורח: מומחה ריצוף', 'אריחים, פרקט וחיפויים – מה מתאים לכל חלל ואיך לא להתחרט.', array['סוגי חומרים', 'עמידות ותחזוקה', 'התאמה לסגנון']::text[], null, null, null, null, null, '{"en":{"title":"Flooring and cladding: choose once, choose right","guest":"Guest: Flooring expert","desc":"Tiles, parquet and cladding – what suits each space and how not to regret it.","points":["Types of materials","Durability and maintenance","Matching the style"]},"ru":{"title":"Напольные покрытия и облицовка: выбрать один раз и правильно","guest":"Гость: эксперт по напольным покрытиям","desc":"Плитка, паркет и облицовка — что подходит для каждого помещения и как не пожалеть о выборе.","points":["Виды материалов","Износостойкость и уход","Соответствие стилю"]},"fr":{"title":"Sols et revêtements : choisir une fois, et bien","guest":"Invité : expert en revêtements de sol","desc":"Carrelage, parquet et revêtements – ce qui convient à chaque pièce et comment ne pas le regretter.","points":["Les types de matériaux","Résistance et entretien","L’accord avec le style"]}}'::jsonb, 'published', 16),
  ('ep-17', 17, 38, 'התחדשות עירונית מבפנים', 'אורח: מנהל פרויקטי התחדשות', 'מה באמת קורה מאחורי הקלעים של פרויקט תמ"א ופינוי בינוי.', array['מול הרשויות', 'ניהול הדיירים', 'לוחות זמנים']::text[], null, null, null, null, null, '{"en":{"title":"Urban renewal from the inside","guest":"Guest: Urban renewal project manager","desc":"What really happens behind the scenes of a TAMA 38 or urban renewal project.","points":["Working with the authorities","Managing the residents","Timelines"]},"ru":{"title":"Городское обновление изнутри","guest":"Гость: руководитель проектов обновления","desc":"Что на самом деле происходит за кулисами проектов ТАМА 38 и «снос-строительство».","points":["Работа с властями","Работа с жильцами","Сроки"]},"fr":{"title":"Le renouvellement urbain de l’intérieur","guest":"Invité : chef de projets de renouvellement","desc":"Ce qui se passe vraiment en coulisses d’un projet TAMA 38 ou de renouvellement urbain.","points":["Face aux autorités","La gestion des résidents","Les calendriers"]}}'::jsonb, 'published', 17),
