insert into public.info_articles (slug, icon_svg, title_he, card_text_he, intro_he, bullets_he, tip_he, image_path, image_alt, i18n, status, sort_order) values
  ('renovation', '<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>', 'מה חשוב לדעת שמתכננים שיפוץ או רוצים לבצע שינוי במבנה קיים', 'לפני שמזיזים קיר אחד: היתרים, תכנון ולוחות זמנים שיחסכו לכם כאב ראש.', 'שיפוץ טוב מתחיל הרבה לפני הפטיש הראשון – בתכנון נכון שחוסך כסף, זמן ועוגמת נפש.', array['בדקו מראש אם השינוי דורש היתר בנייה או אישור מהרשות המקומית.', 'קיר נושא, מערכות חשמל ואינסטלציה – לא נוגעים בלי מהנדס ובעלי מקצוע מוסמכים.', 'הגדירו סדר עבודה ולוח זמנים ברור לפני שמתחילים.', 'השאירו 10%–15% מהתקציב לבלתי צפוי.']::text[], 'צלמו ותעדו את המצב הקיים לפני תחילת העבודות – זה שווה זהב בכל שלב.', null, null, '{"en":{"title":"What to know when planning a renovation or a change to an existing building","teaser":"Before moving a single wall: permits, planning and timelines that will save you headaches.","intro":"A good renovation starts long before the first hammer – with proper planning that saves money, time and heartache.","bullets":["Check in advance whether the change requires a building permit or approval from the local authority.","Load-bearing walls, electrical and plumbing systems – never touch them without an engineer and licensed professionals.","Set a clear work order and timeline before you start.","Keep 10%–15% of the budget for the unexpected."],"tip":"Photograph and document the existing condition before work begins – it’s worth gold at every stage."},"ru":{"title":"Что важно знать, планируя ремонт или изменения в существующем здании","teaser":"Прежде чем сдвинуть хоть одну стену: разрешения, планирование и сроки, которые избавят вас от головной боли.","intro":"Хороший ремонт начинается задолго до первого удара молотка — с правильного планирования, которое экономит деньги, время и нервы.","bullets":["Заранее узнайте, требуется ли для изменений разрешение на строительство или согласование с местными властями.","Несущие стены, электрика и сантехника — не трогайте их без инженера и лицензированных специалистов.","Определите чёткий порядок работ и график до начала.","Оставьте 10–15% бюджета на непредвиденные расходы."],"tip":"Сфотографируйте и задокументируйте исходное состояние до начала работ — это бесценно на любом этапе."},"fr":{"title":"Ce qu’il faut savoir avant de rénover ou de modifier un bâtiment existant","teaser":"Avant de déplacer un seul mur : permis, planification et délais qui vous éviteront bien des soucis.","intro":"Une bonne rénovation commence bien avant le premier coup de marteau – par une bonne planification qui fait gagner de l’argent, du temps et évite bien des tracas.","bullets":["Vérifiez à l’avance si la modification nécessite un permis de construire ou l’accord de la municipalité.","Murs porteurs, électricité et plomberie – on n’y touche pas sans ingénieur ni professionnels agréés.","Fixez un ordre des travaux et un calendrier clairs avant de commencer.","Gardez 10 à 15 % du budget pour les imprévus."],"tip":"Photographiez et documentez l’état existant avant le début des travaux – cela vaut de l’or à chaque étape."}}'::jsonb, 'published', 1),
  ('private-home', '<path d="M3 10.5 12 3l9 7.5"/><path d="M5 9v12h14V9"/><path d="M10 21v-6h4v6"/>', 'איך בונים בית פרטי בצורה היעילה ביותר', 'הדרך הקצרה מהחלום למפתח, צעד אחר צעד.', 'בית פרטי הוא פרויקט חיים – וכשמנהלים אותו נכון, החלום הופך למפתח בלי לאבד את הדרך.', array['התחילו בבדיקת זכויות הבנייה והתב"ע של המגרש.', 'צוות אחד שמתאם תכנון, הנדסה וביצוע חוסך פערים וטעויות יקרות.', 'תוכניות מפורטות ומפרט טכני ברור = הצעות מחיר מדויקות.', 'לוח זמנים עם אבני דרך מאפשר לכם לדעת בכל רגע איפה הפרויקט עומד.']::text[], 'החלטות על מטבח, ריצוף ותאורה כדאי לקבל כבר בשלב התכנון – לא באמצע הבנייה.', null, null, '{"en":{"title":"How to build a private home in the most efficient way","teaser":"The short road from dream to key, step by step.","intro":"A private home is a life project – and when it’s managed right, the dream becomes a key without losing your way.","bullets":["Start by checking the plot’s building rights and zoning plan.","One team coordinating design, engineering and execution saves gaps and costly mistakes.","Detailed plans and a clear technical specification = accurate quotes.","A timeline with milestones lets you know at any moment where the project stands."],"tip":"Decisions on the kitchen, flooring and lighting are best made at the planning stage – not in the middle of construction."},"ru":{"title":"Как построить частный дом наиболее эффективно","teaser":"Короткий путь от мечты до ключа, шаг за шагом.","intro":"Частный дом — проект всей жизни, и при правильном управлении мечта превращается в ключ, не сбившись с пути.","bullets":["Начните с проверки прав на застройку и градостроительного плана участка.","Одна команда, координирующая проектирование, инженерию и строительство, избавляет от нестыковок и дорогих ошибок.","Подробные чертежи и чёткая техническая спецификация = точные сметы.","График с контрольными точками позволяет в любой момент знать, на каком этапе проект."],"tip":"Решения о кухне, напольном покрытии и освещении лучше принимать на этапе проектирования, а не посреди стройки."},"fr":{"title":"Comment construire une maison de la manière la plus efficace","teaser":"Le chemin le plus court du rêve à la clé, étape par étape.","intro":"Une maison individuelle est le projet d’une vie – bien gérée, le rêve devient une clé sans perdre le cap.","bullets":["Commencez par vérifier les droits à construire et le plan d’urbanisme du terrain.","Une seule équipe qui coordonne conception, ingénierie et exécution évite les décalages et les erreurs coûteuses.","Des plans détaillés et un cahier des charges clair = des devis précis.","Un calendrier avec des jalons vous permet de savoir à tout moment où en est le projet."],"tip":"Les choix de cuisine, de sols et d’éclairage se font dès la conception – pas en plein chantier."}}'::jsonb, 'published', 2),
  ('weather', '<path d="M12 3a9 9 0 0 1 9 9H3a9 9 0 0 1 9-9z"/><path d="M12 12v7a2 2 0 0 1-4 0"/><path d="M12 1.5V3"/>', 'מדוע חשוב לשמור על מבנה מפני מזג האוויר והנזקים שנגרמים מחוסר שמירה', 'איטום, בידוד ותחזוקה מונעת – כי נזק קטן היום הוא הוצאה גדולה מחר.', 'גשם, שמש ורוח עובדים על המבנה שלכם כל יום. מי שמקדים – חוסך.', array['איטום גגות ומרפסות הוא קו ההגנה הראשון מפני רטיבות ועובש.', 'סדקים קטנים בחזית הם הזמנה לחדירת מים – מטפלים בהם מוקדם.', 'בידוד נכון שומר על נוחות בבית ומוריד את חשבון החשמל.', 'בדיקה לפני החורף שווה יותר מתיקון אחריו.']::text[], 'קבעו בדיקת איטום תקופתית פעם בשנה, רגע לפני עונת הגשמים.', null, null, '{"en":{"title":"Why protect a building from the weather and from the damage caused by neglect","teaser":"Sealing, insulation and preventive maintenance – because small damage today is a big expense tomorrow.","intro":"Rain, sun and wind work on your building every day. Acting early saves money.","bullets":["Waterproofing roofs and balconies is the first line of defense against damp and mold.","Small cracks in the facade invite water in – treat them early.","Proper insulation keeps the home comfortable and lowers the electricity bill.","An inspection before winter is worth more than a repair after it."],"tip":"Schedule a waterproofing inspection once a year, just before the rainy season."},"ru":{"title":"Почему важно защищать здание от непогоды и от ущерба из-за отсутствия ухода","teaser":"Гидроизоляция, утепление и профилактика — ведь маленькое повреждение сегодня — большие расходы завтра.","intro":"Дождь, солнце и ветер воздействуют на ваше здание каждый день. Кто действует заранее — экономит.","bullets":["Гидроизоляция крыш и балконов — первая линия защиты от сырости и плесени.","Мелкие трещины на фасаде — приглашение для воды; устраняйте их вовремя.","Правильная теплоизоляция сохраняет комфорт в доме и снижает счета за электричество.","Проверка перед зимой стоит больше, чем ремонт после неё."],"tip":"Назначайте проверку гидроизоляции раз в год, прямо перед сезоном дождей."},"fr":{"title":"Pourquoi protéger un bâtiment des intempéries et des dégâts dus au manque d’entretien","teaser":"Étanchéité, isolation et entretien préventif – car un petit dégât aujourd’hui est une grosse dépense demain.","intro":"Pluie, soleil et vent agissent sur votre bâtiment chaque jour. Anticiper, c’est économiser.","bullets":["L’étanchéité des toits et des balcons est la première ligne de défense contre l’humidité et les moisissures.","Les petites fissures en façade laissent entrer l’eau – traitez-les tôt.","Une bonne isolation garde la maison confortable et réduit la facture d’électricité.","Une inspection avant l’hiver vaut mieux qu’une réparation après."],"tip":"Programmez un contrôle d’étanchéité une fois par an, juste avant la saison des pluies."}}'::jsonb, 'published', 3),
  ('budget', '<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M8 6h8"/><path d="M8 11h.01M12 11h.01M16 11h.01M8 15h.01M12 15h.01M16 15h.01M8 18.5h.01M12 18.5h.01M16 18.5h.01"/>', 'איך מתכננים תקציב ומה חשוב לדעת', 'איך בונים תקציב מציאותי, משאירים מקום לבלתי צפוי ושומרים על שליטה.', 'תקציב טוב הוא לא רק מספר – הוא תוכנית שמשאירה אתכם בשליטה מההתחלה ועד המסירה.', array['פרקו את התקציב לפי שלבים: תכנון, שלד, מערכות, גמר ומוצרים נלווים.', 'השוו הצעות מחיר לפי אותו מפרט בדיוק – אחרת משווים תפוחים לתפוזים.', 'הגדירו מראש רזרבה לבלתי צפוי.', 'עקבו אחרי ההוצאות לאורך הדרך, לא רק בסוף.']::text[], '"הכי זול" בהתחלה יוצא לא פעם "הכי יקר" בסוף – בחרו לפי איכות ואחריות.', null, null, '{"en":{"title":"How to plan a budget and what to know","teaser":"How to build a realistic budget, leave room for the unexpected and stay in control.","intro":"A good budget isn’t just a number – it’s a plan that keeps you in control from start to handover.","bullets":["Break the budget into stages: planning, structure, systems, finishing and complementary products.","Compare quotes against exactly the same specification – otherwise you’re comparing apples to oranges.","Set a reserve for the unexpected in advance.","Track expenses along the way, not just at the end."],"tip":"\"The cheapest\" at the start often turns out \"the most expensive\" in the end – choose by quality and warranty."},"ru":{"title":"Как спланировать бюджет и что важно знать","teaser":"Как составить реалистичный бюджет, оставить место для непредвиденного и сохранить контроль.","intro":"Хороший бюджет — это не просто число, а план, который держит всё под вашим контролем от начала до сдачи.","bullets":["Разбейте бюджет по этапам: проектирование, каркас, инженерные системы, отделка и сопутствующие товары.","Сравнивайте сметы строго по одной и той же спецификации — иначе вы сравниваете яблоки с апельсинами.","Заранее заложите резерв на непредвиденное.","Отслеживайте расходы по ходу работ, а не только в конце."],"tip":"«Самое дешёвое» в начале нередко оказывается «самым дорогим» в конце — выбирайте по качеству и гарантии."},"fr":{"title":"Comment planifier un budget et ce qu’il faut savoir","teaser":"Comment bâtir un budget réaliste, prévoir l’imprévu et garder le contrôle.","intro":"Un bon budget n’est pas qu’un chiffre – c’est un plan qui vous garde maître du projet du début à la livraison.","bullets":["Découpez le budget par étapes : conception, gros œuvre, réseaux, finitions et produits complémentaires.","Comparez les devis sur exactement le même cahier des charges – sinon on compare des pommes et des oranges.","Prévoyez d’avance une réserve pour les imprévus.","Suivez les dépenses tout au long du projet, pas seulement à la fin."],"tip":"« Le moins cher » au départ finit souvent « le plus cher » à l’arrivée – choisissez la qualité et la garantie."}}'::jsonb, 'published', 4),
  ('dangerous', '<path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><path d="M12 9v4"/><path d="M12 17h.01"/>', 'מבנה מסוכן – מה חשוב לדעת', 'סימני אזהרה, חובות הבעלים ומתי חייבים לפנות לאיש מקצוע מיד.', 'סדק, שקיעה או בטון מתפורר הם לא רק בעיה אסתטית – לפעמים הם סימן אזהרה.', array['סדקים מתרחבים, ברזל חשוף או רצפה ששוקעת – דורשים בדיקת מהנדס בהקדם.', 'לבעלי המבנה יש אחריות לתחזוקה ולבטיחות הדיירים והעוברים.', 'טיפול מוקדם זול ובטוח בהרבה מתיקון אחרי נזק.', 'חיזוק מבנה נעשה לפי תכנון הנדסי בלבד.']::text[], 'כשיש ספק – אין ספק. הזמינו בדיקה מקצועית לפני שמחכים לנזק.', null, null, '{"en":{"title":"Dangerous buildings – what to know","teaser":"Warning signs, owners’ duties and when you must call a professional right away.","intro":"A crack, subsidence or crumbling concrete isn’t just a cosmetic issue – sometimes it’s a warning sign.","bullets":["Widening cracks, exposed rebar or a sinking floor – require an engineer’s inspection as soon as possible.","Building owners are responsible for maintenance and for the safety of residents and passers-by.","Early treatment is far cheaper and safer than repairs after damage.","Structural reinforcement is done only according to an engineering design."],"tip":"When in doubt – there’s no doubt. Order a professional inspection before damage occurs."},"ru":{"title":"Опасное здание — что важно знать","teaser":"Тревожные признаки, обязанности владельца и когда нужно срочно звать специалиста.","intro":"Трещина, просадка или крошащийся бетон — это не только эстетическая проблема, иногда это тревожный сигнал.","bullets":["Расширяющиеся трещины, оголённая арматура или проседающий пол требуют скорейшей проверки инженера.","Владельцы здания отвечают за его содержание и безопасность жильцов и прохожих.","Ранний ремонт гораздо дешевле и безопаснее, чем исправление последствий.","Усиление конструкций выполняется только по инженерному проекту."],"tip":"Если есть сомнения — сомнений нет. Закажите профессиональную проверку, не дожидаясь ущерба."},"fr":{"title":"Bâtiment dangereux – ce qu’il faut savoir","teaser":"Signes d’alerte, obligations du propriétaire et quand appeler un professionnel sans attendre.","intro":"Une fissure, un affaissement ou un béton qui s’effrite ne sont pas qu’un problème esthétique – c’est parfois un signal d’alerte.","bullets":["Fissures qui s’élargissent, ferraillage apparent ou sol qui s’affaisse – exigent au plus vite l’avis d’un ingénieur.","Les propriétaires sont responsables de l’entretien et de la sécurité des résidents et des passants.","Agir tôt est bien moins cher et plus sûr que réparer après les dégâts.","Le renforcement d’une structure se fait uniquement selon une étude d’ingénierie."],"tip":"Dans le doute, n’hésitez pas : faites faire une inspection professionnelle avant les dégâts."}}'::jsonb, 'published', 5),
  ('heritage', '<path d="M3 21h18"/><path d="M5 21V10M9.5 21V10M14.5 21V10M19 21V10"/><path d="M2 10h20L12 3z"/>', 'מבנה לשימור – מה חשוב לדעת', 'איך משדרגים מבנה היסטורי ושומרים על הנשמה שלו – לפי החוק.', 'למבנה לשימור יש היסטוריה ונשמה – והשדרוג שלו דורש רגישות, ידע ותכנון מדויק.', array['כל שינוי כפוף להנחיות השימור של הרשות המקומית.', 'חומרים ושיטות עבודה צריכים להתאים לאופי המקורי של המבנה.', 'תיעוד ותכנון מוקדם מקצרים את תהליך האישורים.', 'אפשר לשלב מערכות מודרניות בלי לפגוע בערך ההיסטורי.']::text[], 'צוות שמכיר עבודות שיקום ושימור חוסך לכם חודשים של התכתבויות.', null, null, '{"en":{"title":"Heritage buildings – what to know","teaser":"How to upgrade a historic building and keep its soul – by the law.","intro":"A heritage building has history and soul – and upgrading it takes sensitivity, knowledge and precise planning.","bullets":["Every change is subject to the local authority’s preservation guidelines.","Materials and work methods must suit the building’s original character.","Early documentation and planning shorten the approval process.","Modern systems can be integrated without harming the historic value."],"tip":"A team experienced in restoration and preservation saves you months of correspondence."},"ru":{"title":"Здание под охраной — что важно знать","teaser":"Как модернизировать историческое здание и сохранить его душу — по закону.","intro":"У здания под охраной есть история и душа — и его модернизация требует деликатности, знаний и точного планирования.","bullets":["Любые изменения подчиняются требованиям местных властей по охране памятников.","Материалы и методы работ должны соответствовать исходному характеру здания.","Ранняя документация и планирование сокращают процесс согласований.","Современные системы можно встроить, не нарушая историческую ценность."],"tip":"Команда с опытом реставрации и сохранения зданий избавит вас от месяцев переписки."},"fr":{"title":"Bâtiment classé – ce qu’il faut savoir","teaser":"Comment rénover un bâtiment historique en préservant son âme – selon la loi.","intro":"Un bâtiment classé a une histoire et une âme – sa rénovation exige délicatesse, savoir-faire et une planification précise.","bullets":["Toute modification est soumise aux directives de conservation de la municipalité.","Les matériaux et les méthodes doivent respecter le caractère d’origine du bâtiment.","Une documentation et une planification précoces raccourcissent les autorisations.","On peut intégrer des équipements modernes sans nuire à la valeur historique."],"tip":"Une équipe rompue à la restauration et à la conservation vous épargne des mois de correspondance."}}'::jsonb, 'published', 6),
  ('maintenance', '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/><path d="m9 16 2 2 4-4"/>', 'תחזוקה שוטפת ומה חשוב', 'מה בודקים, מתי ולמה – לבית שנשאר כמו חדש.', 'מבנה מתוחזק שומר על הערך שלו – ועל השקט שלכם.', array['בדיקות תקופתיות למערכות חשמל, אינסטלציה, מיזוג ואיטום.', 'ניקוי מרזבים ונקזים לפני החורף מונע הצפות ורטיבות.', 'טיפול מיידי בתקלות קטנות מונע תקלות גדולות.', 'תיק מבנה מסודר עם כל המסמכים והאחריות חוסך זמן בכל פנייה.']::text[], 'מנוי שירות ואחזקה שומר על המבנה במצב מעולה – בלי שתצטרכו לזכור כלום.', null, null, '{"en":{"title":"Routine maintenance and what matters","teaser":"What to check, when and why – for a home that stays like new.","intro":"A well-maintained building keeps its value – and your peace of mind.","bullets":["Periodic checks of electrical, plumbing, air-conditioning and waterproofing systems.","Cleaning gutters and drains before winter prevents flooding and damp.","Fixing small faults right away prevents big ones.","An organized building file with all documents and warranties saves time on every request."],"tip":"A service and maintenance plan keeps the building in excellent shape – without you having to remember a thing."},"ru":{"title":"Регулярное обслуживание и что важно","teaser":"Что проверять, когда и зачем — чтобы дом оставался как новый.","intro":"Ухоженное здание сохраняет свою ценность — и ваше спокойствие.","bullets":["Периодические проверки электрики, сантехники, кондиционирования и гидроизоляции.","Чистка водостоков и сливов перед зимой предотвращает затопления и сырость.","Немедленное устранение мелких неисправностей предотвращает крупные.","Аккуратное досье здания со всеми документами и гарантиями экономит время при каждом обращении."],"tip":"Абонемент на обслуживание держит здание в отличном состоянии — и вам не нужно ничего помнить."},"fr":{"title":"L’entretien courant et ce qui compte","teaser":"Quoi vérifier, quand et pourquoi – pour une maison qui reste comme neuve.","intro":"Un bâtiment bien entretenu garde sa valeur – et votre tranquillité.","bullets":["Contrôles réguliers de l’électricité, de la plomberie, de la climatisation et de l’étanchéité.","Nettoyer gouttières et évacuations avant l’hiver évite inondations et humidité.","Régler tout de suite les petites pannes évite les grosses.","Un dossier du bâtiment bien tenu, avec documents et garanties, fait gagner du temps à chaque démarche."],"tip":"Un contrat d’entretien garde le bâtiment en excellent état – sans que vous ayez à y penser."}}'::jsonb, 'published', 7),
  ('safety', '<path d="M2 18a1 1 0 0 0 1 1h18a1 1 0 0 0 1-1v-2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1z"/><path d="M10 15V6.5a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1V15"/><path d="M4 15v-3a6 6 0 0 1 6-6"/><path d="M14 6a6 6 0 0 1 6 6v3"/>', 'בטיחות בעבודה', 'הכללים שמגנים על העובדים, על הדיירים ועל הפרויקט.', 'באתר בנייה, בטיחות היא לא סעיף בחוזה – היא הבסיס לכל יום עבודה.', array['גידור ושילוט האתר מגנים על העובדים, על הדיירים ועל העוברים ושבים.', 'עבודה בגובה רק עם ציוד מתאים ובעלי מקצוע מוסמכים.', 'מנהל עבודה רשום אחראי על הבטיחות באתר.', 'מצלמות ובקרה באתר מוסיפות שכבת ביטחון ושקיפות.']::text[], 'אצלנו כל פרויקט מרושת במצלמות אבטחה 24/7 עוד לפני תחילת העבודות.', null, null, '{"en":{"title":"Safety at work","teaser":"The rules that protect the workers, the residents and the project.","intro":"On a construction site, safety isn’t a clause in the contract – it’s the foundation of every working day.","bullets":["Fencing and signage protect the workers, the residents and passers-by.","Work at height only with proper equipment and certified professionals.","A registered site manager is responsible for safety on site.","Cameras and monitoring on site add a layer of security and transparency."],"tip":"With us, every project is covered by 24/7 security cameras even before work begins."},"ru":{"title":"Безопасность труда","teaser":"Правила, которые защищают рабочих, жильцов и проект.","intro":"На стройке безопасность — не пункт договора, а основа каждого рабочего дня.","bullets":["Ограждение и знаки на площадке защищают рабочих, жильцов и прохожих.","Работы на высоте — только с подходящим снаряжением и сертифицированными специалистами.","Зарегистрированный прораб отвечает за безопасность на площадке.","Камеры и контроль на площадке добавляют безопасности и прозрачности."],"tip":"У нас каждый проект оснащается камерами наблюдения 24/7 ещё до начала работ."},"fr":{"title":"La sécurité au travail","teaser":"Les règles qui protègent les ouvriers, les résidents et le projet.","intro":"Sur un chantier, la sécurité n’est pas une clause du contrat – c’est la base de chaque journée de travail.","bullets":["Clôtures et signalisation protègent les ouvriers, les résidents et les passants.","Travail en hauteur uniquement avec l’équipement adapté et des professionnels certifiés.","Un chef de chantier agréé est responsable de la sécurité sur le site.","Caméras et surveillance sur le chantier ajoutent sécurité et transparence."],"tip":"Chez nous, chaque projet est équipé de caméras de sécurité 24h/24 avant même le début des travaux."}}'::jsonb, 'published', 8),
  ('contractor', '<circle cx="9" cy="7" r="4"/><path d="M2 21v-2a4 4 0 0 1 4-4h6a4 4 0 0 1 4 4v2"/><path d="m16 11 2 2 4-4"/>', 'בחירת קבלן ובעלי מקצוע', 'השאלות הנכונות, הבדיקות שחובה לעשות והסימנים שכדאי לשים לב אליהם.', 'הבחירה הנכונה של קבלן היא ההחלטה החשובה ביותר בפרויקט.', array['בדקו רישיון, ביטוח וניסיון בפרויקטים דומים.', 'בקשו לראות עבודות קודמות ולדבר עם לקוחות.', 'חוזה מפורט עם מפרט, לוחות זמנים ותנאי אחריות – חובה.', 'זמינות ותקשורת שוטפת חשובות לא פחות מהמחיר.']::text[], 'עבודה מול גוף אחד שמתאם את כל בעלי המקצוע חוסכת לכם את "הריצות" בין קבלנים.', null, null, '{"en":{"title":"Choosing a contractor and professionals","teaser":"The right questions, the must-do checks and the signs worth noticing.","intro":"Choosing the right contractor is the most important decision in the project.","bullets":["Check licensing, insurance and experience with similar projects.","Ask to see previous work and talk to clients.","A detailed contract with specifications, timelines and warranty terms – a must.","Availability and ongoing communication matter as much as the price."],"tip":"Working with one body that coordinates all the professionals saves you running around between contractors."},"ru":{"title":"Выбор подрядчика и мастеров","teaser":"Правильные вопросы, обязательные проверки и признаки, на которые стоит обратить внимание.","intro":"Правильный выбор подрядчика — самое важное решение в проекте.","bullets":["Проверьте лицензию, страховку и опыт в похожих проектах.","Попросите показать прошлые работы и поговорите с клиентами.","Подробный договор со спецификацией, сроками и условиями гарантии обязателен.","Доступность и постоянная связь важны не меньше цены."],"tip":"Работа с одной компанией, координирующей всех специалистов, избавит вас от беготни между подрядчиками."},"fr":{"title":"Choisir un entrepreneur et des artisans","teaser":"Les bonnes questions, les vérifications indispensables et les signes à surveiller.","intro":"Bien choisir son entrepreneur est la décision la plus importante du projet.","bullets":["Vérifiez la licence, l’assurance et l’expérience sur des projets similaires.","Demandez à voir des réalisations et à parler à d’anciens clients.","Un contrat détaillé avec cahier des charges, délais et garanties – indispensable.","La disponibilité et une communication suivie comptent autant que le prix."],"tip":"Un interlocuteur unique qui coordonne tous les corps de métier vous évite de courir entre les entrepreneurs."}}'::jsonb, 'published', 9),
  ('products', '<path d="M12 22a10 10 0 1 1 10-10c0 2.8-2.2 4-4 4h-2a2 2 0 0 0-1.5 3.3A1.6 1.6 0 0 1 12 22z"/><circle cx="7.5" cy="10.5" r="1"/><circle cx="10.5" cy="7" r="1"/><circle cx="15" cy="7.5" r="1"/>', 'בחירת מוצרים נלווים לפרויקט ואיך בוחרים', 'ריצוף, מטבח, תאורה ודלתות – איך בוחרים נכון, יפה ומשתלם.', 'ריצוף, מטבח, תאורה ודלתות – הבחירות האלה הן מה שהופך מבנה לבית.', array['בחרו מוצרים שמתאימים לסגנון, לשימוש היומיומי ולתקציב.', 'שימו לב לאחריות, לזמינות חלפים ולזמני אספקה.', 'קבלו החלטות מוקדם כדי לא לעכב את הביצוע.', 'ראו ומששו את המוצרים לפני שמזמינים – תמונה לא תמיד מספרת הכל.']::text[], 'באולם התצוגה שלנו (בקרוב...) תוכלו לבחור הכל במקום אחד, עם ליווי אישי.', null, null, '{"en":{"title":"Choosing complementary products for the project – and how","teaser":"Flooring, kitchen, lighting and doors – how to choose right, beautiful and worthwhile.","intro":"Flooring, kitchen, lighting and doors – these choices are what turn a building into a home.","bullets":["Choose products that suit your style, daily use and budget.","Pay attention to warranty, spare-part availability and delivery times.","Decide early so as not to delay the work.","See and touch the products before ordering – a picture doesn’t always tell the whole story."],"tip":"In our showroom (coming soon...) you’ll be able to choose everything in one place, with personal guidance."},"ru":{"title":"Выбор сопутствующих товаров для проекта и как выбирать","teaser":"Плитка, кухня, освещение и двери — как выбрать правильно, красиво и выгодно.","intro":"Плитка, кухня, освещение и двери — именно этот выбор превращает здание в дом.","bullets":["Выбирайте товары, подходящие вашему стилю, повседневному использованию и бюджету.","Обращайте внимание на гарантию, наличие запчастей и сроки поставки.","Принимайте решения заранее, чтобы не задерживать работы.","Посмотрите и потрогайте товары до заказа — фото не всегда говорит всё."],"tip":"В нашем выставочном зале (скоро...) вы сможете выбрать всё в одном месте с личным сопровождением."},"fr":{"title":"Choisir les produits complémentaires du projet – et comment","teaser":"Sols, cuisine, éclairage et portes – bien choisir, beau et rentable.","intro":"Sols, cuisine, éclairage et portes – ce sont ces choix qui font d’un bâtiment un foyer.","bullets":["Choisissez des produits adaptés à votre style, à l’usage quotidien et au budget.","Faites attention à la garantie, à la disponibilité des pièces et aux délais de livraison.","Décidez tôt pour ne pas retarder les travaux.","Voyez et touchez les produits avant de commander – une photo ne dit pas tout."],"tip":"Dans notre showroom (bientôt...) vous pourrez tout choisir au même endroit, avec un accompagnement personnalisé."}}'::jsonb, 'published', 10),
  ('defects', '<circle cx="11" cy="11" r="7"/><path d="m21 21-4.3-4.3"/><path d="M10 6.5 12 9.5l-2 2 2 2.5"/>', 'ליקויי בנייה וטיפול בהם', 'מסדקים ועד רטיבות: מה הזכויות שלכם ואיך מתקנים נכון.', 'רטיבות, סדקים או ריצוף שקוע – ליקוי בנייה מטפלים בו נכון, ולא מחכים שיחמיר.', array['תעדו את הליקוי בתמונות ובתאריכים.', 'בדיקת מהנדס או בודק מוסמך מגדירה את הבעיה והפתרון.', 'בדירה חדשה – בדקו את תקופת הבדק והאחריות שלכם.', 'תיקון שורש הבעיה חשוב יותר מ"איפור" מהיר.']::text[], 'אנחנו מאתרים את מקור הבעיה – ומתקנים אותה פעם אחת ולתמיד.', null, null, '{"en":{"title":"Construction defects and how to handle them","teaser":"From cracks to damp: what your rights are and how to fix it right.","intro":"Damp, cracks or sunken flooring – a construction defect should be handled properly, not left to get worse.","bullets":["Document the defect with photos and dates.","An inspection by an engineer or certified inspector defines the problem and the solution.","In a new apartment – check your inspection and warranty period.","Fixing the root of the problem matters more than a quick cosmetic fix."],"tip":"We find the source of the problem – and fix it once and for all."},"ru":{"title":"Строительные дефекты и их устранение","teaser":"От трещин до сырости: каковы ваши права и как правильно всё исправить.","intro":"Сырость, трещины или просевшая плитка — дефект нужно устранять правильно и не ждать, пока станет хуже.","bullets":["Задокументируйте дефект фотографиями с датами.","Проверка инженера или сертифицированного эксперта определяет проблему и решение.","В новой квартире проверьте гарантийный срок и период устранения дефектов.","Устранить причину проблемы важнее, чем быстро «замаскировать» её."],"tip":"Мы находим источник проблемы — и устраняем его раз и навсегда."},"fr":{"title":"Les malfaçons et leur traitement","teaser":"Des fissures à l’humidité : vos droits et comment bien réparer.","intro":"Humidité, fissures ou carrelage affaissé – une malfaçon se traite correctement, sans attendre qu’elle s’aggrave.","bullets":["Documentez la malfaçon avec photos et dates.","L’expertise d’un ingénieur ou d’un inspecteur agréé définit le problème et la solution.","Dans un logement neuf – vérifiez votre période de garantie et de parfait achèvement.","Traiter la cause compte plus qu’un « maquillage » rapide."],"tip":"Nous trouvons la source du problème – et la réglons une fois pour toutes."}}'::jsonb, 'published', 11),
  ('planning', '<path d="M3 17 17 3l4 4L7 21H3z"/><path d="m7 13 2 2M10 10l2 2M13 7l2 2"/>', 'מדוע צריך לתכנן כל פרויקט בצורה נכונה ומה הסיכונים שלא כדאי לקחת', 'תכנון נכון מההתחלה חוסך זמן, כסף ועצבים.', 'כל שעה של תכנון חוסכת ימים של תיקונים.', array['בלי תכנון – שינויים באמצע הדרך מייקרים ומעכבים.', 'תיאום בין אדריכל, מהנדס וקבלן מונע טעויות ביצוע.', 'תכנון נכון כולל גם עמידה בתקנים ובדרישות הרשויות.', 'לוח זמנים ותקציב מבוססים נותנים לכם ודאות.']::text[], 'תכנון נכון, חיסכון מוכח – זה העיקרון שמנחה אותנו בכל פרויקט.', null, null, '{"en":{"title":"Why every project must be planned properly – and the risks not worth taking","teaser":"Planning right from the start saves time, money and nerves.","intro":"Every hour of planning saves days of repairs.","bullets":["Without planning – changes midway raise costs and cause delays.","Coordination between architect, engineer and contractor prevents execution errors.","Proper planning also means meeting standards and authority requirements.","A well-founded timeline and budget give you certainty."],"tip":"Right planning, proven savings – that’s the principle guiding us in every project."},"ru":{"title":"Почему каждый проект нужно правильно планировать и какие риски не стоит брать","teaser":"Правильное планирование с самого начала экономит время, деньги и нервы.","intro":"Каждый час планирования экономит дни исправлений.","bullets":["Без планирования изменения по ходу работ удорожают и затягивают проект.","Согласованность архитектора, инженера и подрядчика предотвращает ошибки исполнения.","Правильное планирование включает и соответствие нормам и требованиям властей.","Обоснованные график и бюджет дают вам уверенность."],"tip":"Правильное планирование — доказанная экономия: этот принцип ведёт нас в каждом проекте."},"fr":{"title":"Pourquoi bien planifier chaque projet – et les risques à ne pas prendre","teaser":"Bien planifier dès le départ fait gagner du temps, de l’argent et des nerfs.","intro":"Chaque heure de planification épargne des jours de réparations.","bullets":["Sans planification – les changements en cours de route coûtent cher et retardent.","La coordination entre architecte, ingénieur et entrepreneur évite les erreurs d’exécution.","Bien planifier, c’est aussi respecter les normes et les exigences des autorités.","Un calendrier et un budget solides vous apportent de la certitude."],"tip":"Bonne planification, économies prouvées – c’est le principe qui nous guide dans chaque projet."}}'::jsonb, 'published', 12),
  ('restoration', '<path d="M2 21h10"/><path d="M3.5 21V9.5L10 4l6.5 5.5V12"/><path d="M7.5 21v-5h4v5"/><path d="M7.5 11h5"/><path d="M13 18l4-4 4.5 4.5-4 4z"/><path d="M19.2 16.2 22 13.4"/>', 'שיקום ושימור מבנים – מה חשוב לדעת', 'מחזירים למבנה את הכבוד שלו – חזק, בטוח ויפה כמו ביום הראשון.', 'שיקום נכון מאריך את חיי המבנה, משפר את הבטיחות ומעלה את ערכו – בלי לאבד את האופי שלו.', array['הכל מתחיל בסקר הנדסי שממפה את מצב השלד, החזיתות והמערכות.', 'חיזוק, איטום ושיקום חזיתות נעשים לפי סדר עבודה מתוכנן – מהיסודות כלפי מעלה.', 'במבנה לשימור כל פעולה כפופה להנחיות הרשות ולתיק התיעוד.', 'שילוב חומרים מודרניים עם שמירה על המראה המקורי – זה כל הסוד.']::text[], 'שיקום מבנים הוא אחת מחטיבות הליבה שלנו – מהסקר ועד המסירה, תחת קורת גג אחת.', null, null, '{"en":{"title":"Building restoration and preservation – what to know","teaser":"Restoring a building’s dignity – strong, safe and beautiful as on day one.","intro":"Proper restoration extends a building’s life, improves safety and raises its value – without losing its character.","bullets":["It all starts with an engineering survey mapping the condition of the structure, facades and systems.","Reinforcement, waterproofing and facade restoration follow a planned work order – from the foundations up.","In a heritage building, every step is subject to the authority’s guidelines and the documentation file.","Combining modern materials while keeping the original look – that’s the whole secret."],"tip":"Building restoration is one of our core divisions – from survey to handover, under one roof."},"ru":{"title":"Реставрация и сохранение зданий — что важно знать","teaser":"Возвращаем зданию его достоинство — прочное, безопасное и красивое, как в первый день.","intro":"Правильная реставрация продлевает жизнь здания, повышает безопасность и стоимость — не теряя его характера.","bullets":["Всё начинается с инженерного обследования состояния каркаса, фасадов и инженерных систем.","Усиление, гидроизоляция и восстановление фасадов идут по плану работ — от фундамента вверх.","В здании под охраной каждое действие подчиняется требованиям властей и документационному досье.","Сочетать современные материалы с сохранением исходного облика — в этом весь секрет."],"tip":"Реставрация зданий — одно из наших ключевых направлений: от обследования до сдачи, под одной крышей."},"fr":{"title":"Restauration et conservation des bâtiments – ce qu’il faut savoir","teaser":"Rendre au bâtiment sa dignité – solide, sûr et beau comme au premier jour.","intro":"Une bonne restauration prolonge la vie du bâtiment, améliore la sécurité et augmente sa valeur – sans perdre son caractère.","bullets":["Tout commence par une expertise technique de l’état de la structure, des façades et des réseaux.","Renforcement, étanchéité et réfection des façades suivent un ordre planifié – des fondations vers le haut.","Dans un bâtiment classé, chaque intervention est soumise aux directives de la municipalité et au dossier de documentation.","Allier matériaux modernes et aspect d’origine – tout le secret est là."],"tip":"La restauration est l’un de nos pôles clés – de l’expertise à la livraison, sous un même toit."}}'::jsonb, 'published', 13),
  ('plumbing', '<path d="M3 10h10a4 4 0 0 1 4 4v1.5"/><path d="M3 6v8"/><path d="M9 10V5.5"/><path d="M6 5.5h6"/><path d="M17 17.5s-2.5 2.6-2.5 4a2.5 2.5 0 0 0 5 0c0-1.4-2.5-4-2.5-4z"/>', 'מערכות אינסטלציה וביוב – מה חשוב לדעת', 'מה שלא רואים – הכי חשוב. צנרת תקינה היא שקט נפשי לשנים.', 'תקלה באינסטלציה מתחילה בטפטוף קטן ונגמרת בנזק גדול. תכנון ותחזוקה נכונים מונעים את זה.', array['בשיפוץ – בדקו את מצב הצנרת הישנה לפני שסוגרים קירות ורצפות.', 'שיפועים נכונים בביוב וניקוז מונעים סתימות והצפות.', 'כתמי רטיבות, ריח או ירידה בלחץ המים – סימנים שלא מתעלמים מהם.', 'עבודה עם אינסטלטור מוסמך וחומרים איכותיים חוסכת תיקונים חוזרים.']::text[], 'צלמו את מסלול הצנרת לפני סגירת הקירות – בעתיד זה יחסוך שבירות מיותרות.', null, null, '{"en":{"title":"Plumbing and sewage systems – what to know","teaser":"What you can’t see matters most. Sound piping means peace of mind for years.","intro":"A plumbing fault starts with a small drip and ends in major damage. Proper planning and maintenance prevent it.","bullets":["When renovating – check the old piping before closing walls and floors.","Correct slopes in sewage and drainage prevent blockages and flooding.","Damp stains, odors or a drop in water pressure – signs you don’t ignore.","Working with a licensed plumber and quality materials saves repeat repairs."],"tip":"Photograph the pipe routes before the walls are closed – it will save needless breaking in the future."},"ru":{"title":"Сантехника и канализация — что важно знать","teaser":"Самое важное — то, чего не видно. Исправные трубы — спокойствие на годы.","intro":"Неисправность сантехники начинается с маленькой капли и заканчивается большим ущербом. Правильное проектирование и обслуживание это предотвращают.","bullets":["При ремонте проверьте старые трубы, прежде чем закрывать стены и полы.","Правильные уклоны канализации и дренажа предотвращают засоры и затопления.","Влажные пятна, запах или падение давления воды — признаки, которые нельзя игнорировать.","Работа с лицензированным сантехником и качественными материалами избавляет от повторных ремонтов."],"tip":"Сфотографируйте трассы труб до закрытия стен — в будущем это избавит от лишнего долбления."},"fr":{"title":"Plomberie et assainissement – ce qu’il faut savoir","teaser":"Ce qu’on ne voit pas compte le plus. Une tuyauterie saine, c’est la tranquillité pour des années.","intro":"Une panne de plomberie commence par une petite fuite et finit en gros dégâts. Une bonne conception et un bon entretien l’évitent.","bullets":["En rénovation – vérifiez l’ancienne tuyauterie avant de refermer murs et sols.","De bonnes pentes d’évacuation et de drainage évitent bouchons et inondations.","Taches d’humidité, odeurs ou baisse de pression – des signes à ne pas ignorer.","Un plombier agréé et des matériaux de qualité évitent les réparations à répétition."],"tip":"Photographiez le tracé des tuyaux avant de refermer les murs – cela évitera des démolitions inutiles plus tard."}}'::jsonb, 'published', 14),
  ('landscaping', '<path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 4.18 2 8 0 5.5-4.78 10-10 10z"/><path d="M2 21c0-3 1.85-5.36 5.08-6C9.5 14.52 12 13 13 12"/>', 'גינון ופיתוח סביבתי', 'הבית מתחיל כבר בשביל הכניסה – חוץ שמזמין, ירוק ומטופח.', 'פיתוח סביבתי נכון מחבר בין המבנה לסביבה, מוסיף ערך לנכס ומשפר את איכות החיים.', array['תכננו ניקוז ושיפועים לפני השתילה – כדי שמי גשם לא יגיעו למבנה.', 'בחרו צמחייה שמתאימה לאקלים ולכמות השמש – וחוסכת במים.', 'שבילים, ריצוף חוץ ותאורת גן יוצרים אווירה ובטיחות גם בלילה.', 'מערכת השקיה חכמה חוסכת מים, זמן וכסף.']::text[], 'תכנון הגינה יחד עם הפרויקט – ולא בסופו – חוסך עבודות כפולות ונותן תוצאה הרמונית.', null, null, '{"en":{"title":"Gardening and landscaping","teaser":"Home starts at the front path – an outdoor space that’s inviting, green and well kept.","intro":"Good landscaping connects the building to its surroundings, adds value to the property and improves quality of life.","bullets":["Plan drainage and slopes before planting – so rainwater doesn’t reach the building.","Choose plants that suit the climate and sun exposure – and save water.","Paths, outdoor paving and garden lighting create atmosphere and safety, even at night.","A smart irrigation system saves water, time and money."],"tip":"Planning the garden together with the project – not at its end – saves double work and gives a harmonious result."},"ru":{"title":"Озеленение и благоустройство территории","teaser":"Дом начинается с дорожки к входу — приветливая, зелёная и ухоженная территория.","intro":"Правильное благоустройство связывает здание с окружением, повышает стоимость недвижимости и качество жизни.","bullets":["Спланируйте дренаж и уклоны до посадки, чтобы дождевая вода не доходила до здания.","Выбирайте растения, подходящие климату и освещённости, — и экономящие воду.","Дорожки, уличное мощение и садовое освещение создают атмосферу и безопасность даже ночью.","Умная система полива экономит воду, время и деньги."],"tip":"Планируйте сад вместе с проектом, а не в конце, — это избавит от двойной работы и даст гармоничный результат."},"fr":{"title":"Jardinage et aménagement paysager","teaser":"La maison commence dès l’allée d’entrée – un extérieur accueillant, vert et soigné.","intro":"Un bon aménagement relie le bâtiment à son environnement, valorise le bien et améliore la qualité de vie.","bullets":["Prévoyez drainage et pentes avant de planter – pour que l’eau de pluie n’atteigne pas le bâtiment.","Choisissez des plantes adaptées au climat et à l’ensoleillement – et économes en eau.","Allées, dallage extérieur et éclairage de jardin créent une ambiance et de la sécurité, même la nuit.","Un arrosage intelligent économise l’eau, le temps et l’argent."],"tip":"Concevoir le jardin avec le projet – et non à la fin – évite les travaux en double et donne un résultat harmonieux."}}'::jsonb, 'published', 15),
  ('electrical', '<path d="M13 2 4 14h7l-1 8 9-12h-7z"/>', 'מערכות חשמל ותקשורת', 'חשמל בטוח ותקשורת חכמה – התשתית השקטה שמניעה את הבית.', 'מערכת חשמל ותקשורת מתוכננת נכון היא בטיחות, נוחות ומוכנות לעתיד – כבר מהיום הראשון.', array['תכננו את מיקום השקעים, המפסקים ונקודות התקשורת לפי השימוש בכל חדר – לפני הטיח.', 'לוח חשמל מותאם לצריכה, עם ממסר פחת והפרדת מעגלים – חובה לבטיחות.', 'הכינו תשתית לרשת, מצלמות, מערכות חכמות ועמדת טעינה לרכב חשמלי.', 'עבודה רק עם חשמלאי מוסמך ובדיקת בודק מוסמך בסיום.']::text[], 'הוסיפו צנרת רזרבה כבר עכשיו – שדרוג עתידי יעלה לכם הרבה פחות.', null, null, '{"en":{"title":"Electrical and communication systems","teaser":"Safe electricity and smart communications – the quiet infrastructure that powers the home.","intro":"A well-planned electrical and communication system means safety, comfort and readiness for the future – from day one.","bullets":["Plan the location of sockets, switches and data points according to how each room is used – before plastering.","A panel sized for the load, with a residual-current device and separate circuits – a must for safety.","Prepare infrastructure for the network, cameras, smart systems and an EV charging point.","Work only with a licensed electrician, with an inspection by a certified inspector at the end."],"tip":"Add spare conduits now – a future upgrade will cost you far less."},"ru":{"title":"Электрика и слаботочные системы","teaser":"Безопасная электрика и умная связь — незаметная инфраструктура, которая приводит дом в движение.","intro":"Правильно спроектированные электрика и связь — это безопасность, удобство и готовность к будущему с первого дня.","bullets":["Спланируйте расположение розеток, выключателей и точек связи под назначение каждой комнаты — до штукатурки.","Электрощит под вашу нагрузку, с УЗО и разделением цепей, — обязательное условие безопасности.","Подготовьте инфраструктуру для сети, камер, умных систем и зарядной станции для электромобиля.","Работайте только с лицензированным электриком и проверкой сертифицированного инспектора в конце."],"tip":"Проложите резервные гофротрубы уже сейчас — будущая модернизация обойдётся намного дешевле."},"fr":{"title":"Électricité et réseaux de communication","teaser":"Une électricité sûre et une communication intelligente – l’infrastructure discrète qui fait vivre la maison.","intro":"Un réseau électrique et de communication bien conçu, c’est la sécurité, le confort et un logement prêt pour l’avenir – dès le premier jour.","bullets":["Prévoyez l’emplacement des prises, interrupteurs et points réseau selon l’usage de chaque pièce – avant l’enduit.","Un tableau électrique adapté à la consommation, avec différentiel et circuits séparés – indispensable pour la sécurité.","Préparez l’infrastructure pour le réseau, les caméras, la domotique et une borne de recharge pour véhicule électrique.","Travaillez uniquement avec un électricien agréé, avec un contrôle par un inspecteur agréé à la fin."],"tip":"Ajoutez des gaines de réserve dès maintenant – une future mise à niveau vous coûtera bien moins cher."}}'::jsonb, 'published', 16),
  ('waterproofing', '<path d="M12 22s8-3.5 8-10V5l-8-3-8 3v7c0 6.5 8 10 8 10z"/><path d="M12 7.5s-3 3.4-3 5.5a3 3 0 0 0 6 0c0-2.1-3-5.5-3-5.5z"/>', 'איטום ובידוד מבנה', 'מגן על המבנה מבחוץ, שומר על נוחות מבפנים.', 'איטום ובידוד נכונים מונעים רטיבות ועובש, חוסכים באנרגיה ומאריכים את חיי המבנה.', array['גגות, מרפסות, חדרים רטובים ומרתפים – האזורים שדורשים איטום מקצועי במיוחד.', 'בחירת חומר האיטום לפי סוג המשטח והחשיפה לשמש ולמים.', 'בידוד תרמי ואקוסטי משפר את איכות החיים ומוריד את חשבון החשמל.', 'בדיקת הצפה אחרי איטום מוודאת שהעבודה בוצעה כמו שצריך.']::text[], 'איטום הוא השקעה ולא הוצאה – תיקון נזקי רטיבות עולה פי כמה.', null, null, '{"en":{"title":"Building waterproofing and insulation","teaser":"Protects the building outside, keeps it comfortable inside.","intro":"Proper waterproofing and insulation prevent damp and mold, save energy and extend the building’s life.","bullets":["Roofs, balconies, wet rooms and basements – the areas that especially need professional waterproofing.","Choose the waterproofing material by surface type and exposure to sun and water.","Thermal and acoustic insulation improves quality of life and lowers the electricity bill.","A flood test after waterproofing confirms the work was done properly."],"tip":"Waterproofing is an investment, not an expense – repairing damp damage costs many times more."},"ru":{"title":"Гидроизоляция и теплоизоляция здания","teaser":"Защищает здание снаружи и сохраняет комфорт внутри.","intro":"Правильные гидро- и теплоизоляция предотвращают сырость и плесень, экономят энергию и продлевают жизнь здания.","bullets":["Крыши, балконы, влажные помещения и подвалы — зоны, которым особенно нужна профессиональная гидроизоляция.","Выбирайте гидроизоляционный материал по типу поверхности и воздействию солнца и воды.","Тепло- и звукоизоляция повышают качество жизни и снижают счета за электричество.","Проверка заливом после гидроизоляции подтверждает, что работа выполнена как следует."],"tip":"Гидроизоляция — это вложение, а не расход: устранение последствий сырости обходится в разы дороже."},"fr":{"title":"Étanchéité et isolation du bâtiment","teaser":"Protège le bâtiment à l’extérieur, préserve le confort à l’intérieur.","intro":"Une étanchéité et une isolation bien faites évitent humidité et moisissures, économisent l’énergie et prolongent la vie du bâtiment.","bullets":["Toits, balcons, pièces d’eau et sous-sols – les zones qui exigent tout particulièrement une étanchéité professionnelle.","Choisissez le matériau d’étanchéité selon le type de surface et l’exposition au soleil et à l’eau.","L’isolation thermique et acoustique améliore la qualité de vie et réduit la facture d’électricité.","Un test d’inondation après l’étanchéité confirme que le travail a été bien fait."],"tip":"L’étanchéité est un investissement, pas une dépense – réparer des dégâts d’humidité coûte plusieurs fois plus cher."}}'::jsonb, 'published', 17),
  ('interior-design', '<path d="M5 11V8a3 3 0 0 1 3-3h8a3 3 0 0 1 3 3v3"/><path d="M3 13a2 2 0 0 1 4 0v2h10v-2a2 2 0 0 1 4 0v4a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M6 18v2M18 18v2"/>', 'עיצוב פנים', 'חללים שמספרים את הסיפור שלכם – יפים, נוחים ומדויקים.', 'עיצוב פנים טוב מחבר בין סגנון, פונקציונליות ותקציב – והופך מבנה לבית שאוהבים לחזור אליו.', array['התחילו מהצרכים: מי גר בבית, איך משתמשים בכל חלל ומה חשוב לכם ביום-יום.', 'הדמיות לפני ביצוע מאפשרות לראות את התוצאה ולשנות לפני שמשקיעים.', 'תאורה, צבעים וחומרים עובדים יחד – בחרו אותם כקונספט אחד ולא כפריטים בודדים.', 'שלבו את עיצוב הפנים כבר בשלב התכנון, כדי שחשמל, אינסטלציה ונגרות יתאימו לעיצוב.']::text[], '"השלב הכי כיפי והמאתגר בפרויקט" – אצלנו מעצבים, מדמים ומבצעים תחת קורת גג אחת.', null, null, '{"en":{"title":"Interior design","teaser":"Spaces that tell your story – beautiful, comfortable and precise.","intro":"Good interior design brings together style, function and budget – and turns a building into a home you love coming back to.","bullets":["Start with your needs: who lives in the home, how each space is used and what matters to you day to day.","Visualizations before execution let you see the result and make changes before you invest.","Lighting, colors and materials work together – choose them as one concept, not as separate items.","Bring interior design in at the planning stage, so electrical, plumbing and carpentry fit the design."],"tip":"\"The most fun and challenging stage of the project\" – with us, you design, visualize and build under one roof."},"ru":{"title":"Дизайн интерьера","teaser":"Пространства, которые рассказывают вашу историю, — красивые, удобные и продуманные.","intro":"Хороший дизайн интерьера объединяет стиль, функциональность и бюджет — и превращает здание в дом, куда хочется возвращаться.","bullets":["Начните с потребностей: кто живёт в доме, как используется каждое пространство и что важно вам в повседневной жизни.","Визуализации до начала работ позволяют увидеть результат и внести изменения до вложений.","Освещение, цвета и материалы работают вместе — выбирайте их как единую концепцию, а не по отдельности.","Подключайте дизайн интерьера уже на этапе проектирования, чтобы электрика, сантехника и столярка соответствовали дизайну."],"tip":"«Самый увлекательный и сложный этап проекта» — у нас дизайн, визуализация и реализация под одной крышей."},"fr":{"title":"Architecture d’intérieur","teaser":"Des espaces qui racontent votre histoire – beaux, confortables et précis.","intro":"Une bonne architecture d’intérieur allie style, fonctionnalité et budget – et fait d’un bâtiment un foyer où l’on aime revenir.","bullets":["Partez de vos besoins : qui vit dans la maison, comment chaque espace est utilisé et ce qui compte pour vous au quotidien.","Les visualisations avant travaux permettent de voir le résultat et de modifier avant d’investir.","Éclairage, couleurs et matériaux fonctionnent ensemble – choisissez-les comme un seul concept, pas élément par élément.","Intégrez l’architecture d’intérieur dès la conception, pour que l’électricité, la plomberie et la menuiserie s’accordent au design."],"tip":"« L’étape la plus amusante et la plus exigeante du projet » – chez nous, on conçoit, on visualise et on réalise sous un même toit."}}'::jsonb, 'published', 18)
insert into public.job_roles (slug, title_he, subtitle_he, intro_he, requirements_he, advantages_he, offer_he, active, i18n, status, sort_order) values
  ('r4', 'אנשי משרד ושירות', 'שירות אישי וחם לכל לקוח', 'איש/אשת משרד ושירות לקוחות לצוות המטה של הקבוצה בהרצליה.', array['ניסיון בעבודה משרדית / שירות לקוחות', 'שליטה בתוכנות Office', 'יחסי אנוש מצוינים ואדיבות', 'יכולת עבודה בסביבה דינמית']::text[], array['ניסיון בחברת בנייה / נדל"ן', 'אנגלית ברמה טובה']::text[], array['עבודה בקבוצה משפחתית ומקצועית', 'פרויקטים מגוונים ומאתגרים', 'תנאים הוגנים ויציבות', 'אפשרויות קידום והתפתחות']::text[], true, '{"en":{"title":"Office & Service Staff","subtitle":"Personal, warm service for every client","intro":"Office and customer service staff member for the group’s headquarters team in Herzliya.","req":["Experience in office work / customer service","Proficiency in Office software","Excellent interpersonal skills and courtesy","Ability to work in a dynamic environment"],"adv":["Experience at a construction / real estate company","Good level of English"],"offer":["Working in a professional, family-run group","Diverse and challenging projects","Fair conditions and stability","Opportunities for promotion and growth"]},"ru":{"title":"Офис и сервис","subtitle":"Личный и тёплый сервис для каждого клиента","intro":"Сотрудник офиса и службы клиентов в команду штаб-квартиры группы в Герцлии.","req":["Опыт офисной работы / обслуживания клиентов","Владение программами Office","Отличные коммуникативные навыки и вежливость","Умение работать в динамичной среде"],"adv":["Опыт работы в строительной компании / сфере недвижимости","Хороший уровень английского"],"offer":["Работа в семейной и профессиональной группе","Разнообразные и интересные проекты","Честные условия и стабильность","Возможности карьерного роста и развития"]},"fr":{"title":"Personnel de bureau et de service","subtitle":"Un service personnel et chaleureux pour chaque client","intro":"Employé(e) de bureau et service client pour l’équipe du siège du groupe à Herzliya.","req":["Expérience en travail de bureau / service client","Maîtrise des logiciels Office","Excellent relationnel et courtoisie","Capacité à travailler dans un environnement dynamique"],"adv":["Expérience dans une entreprise de construction / immobilier","Bon niveau d’anglais"],"offer":["Travailler au sein d’un groupe familial et professionnel","Des projets variés et stimulants","Des conditions équitables et de la stabilité","Des possibilités d’évolution et de développement"]}}'::jsonb, 'published', 1),
  ('r1', 'מנהלי עבודה', 'אחראים על השטח, על לוח הזמנים ועל האיכות', 'מנהל/ת עבודה לפרויקטי בנייה, שיפוץ ותשתיות באזור המרכז וירושלים.', array['תעודת מנהל עבודה רשום', 'ניסיון של 3 שנים לפחות בניהול אתר בנייה', 'היכרות עם תקנות הבטיחות בעבודה', 'יכולת ניהול צוותים וקבלני משנה', 'רישיון נהיגה בתוקף']::text[], array['ניסיון בפרויקטי תמ"א 38 / פינוי בינוי', 'היכרות עם תוכנות לניהול פרויקטים']::text[], array['עבודה בקבוצה משפחתית ומקצועית', 'פרויקטים מגוונים ומאתגרים', 'תנאים הוגנים ויציבות', 'אפשרויות קידום והתפתחות']::text[], true, '{"en":{"title":"Site Managers","subtitle":"In charge of the site, the schedule and the quality","intro":"Site manager for construction, renovation and infrastructure projects in central Israel and Jerusalem.","req":["Registered site manager certificate","At least 3 years of experience managing a construction site","Knowledge of occupational safety regulations","Ability to manage teams and subcontractors","Valid driving licence"],"adv":["Experience in TAMA 38 / urban renewal projects","Familiarity with project management software"],"offer":["Working in a professional, family-run group","Diverse and challenging projects","Fair conditions and stability","Opportunities for promotion and growth"]},"ru":{"title":"Прорабы","subtitle":"Отвечают за площадку, сроки и качество","intro":"Прораб для строительных, ремонтных и инфраструктурных проектов в центре страны и Иерусалиме.","req":["Удостоверение зарегистрированного прораба","Опыт управления стройплощадкой не менее 3 лет","Знание правил техники безопасности","Умение руководить бригадами и субподрядчиками","Действующие водительские права"],"adv":["Опыт в проектах ТАМА 38 / «снос и застройка»","Знание программ управления проектами"],"offer":["Работа в семейной и профессиональной группе","Разнообразные и интересные проекты","Честные условия и стабильность","Возможности карьерного роста и развития"]},"fr":{"title":"Chefs de chantier","subtitle":"Responsables du chantier, du planning et de la qualité","intro":"Chef de chantier pour des projets de construction, de rénovation et d’infrastructures dans le centre du pays et à Jérusalem.","req":["Certificat de chef de chantier agréé","Au moins 3 ans d’expérience en gestion de chantier","Connaissance des règles de sécurité au travail","Capacité à gérer des équipes et des sous-traitants","Permis de conduire valide"],"adv":["Expérience dans des projets TAMA 38 / rénovation urbaine","Maîtrise de logiciels de gestion de projet"],"offer":["Travailler au sein d’un groupe familial et professionnel","Des projets variés et stimulants","Des conditions équitables et de la stabilité","Des possibilités d’évolution et de développement"]}}'::jsonb, 'published', 2),
  ('r3', 'מהנדסים ואדריכלים', 'תכנון והנדסה ברמה הגבוהה ביותר', 'מהנדס/ת ואדריכל/ית לתכנון, ליווי ופיקוח על פרויקטים בתחומי המגורים, המסחר והציבור.', array['תואר בהנדסה אזרחית / אדריכלות', 'רישוי בפנקס המהנדסים והאדריכלים', 'ניסיון של 2 שנים לפחות', 'שליטה ב-AutoCAD ו-Revit']::text[], array['ניסיון בהגשת היתרי בנייה', 'ניסיון בפיקוח עליון באתר']::text[], array['עבודה בקבוצה משפחתית ומקצועית', 'פרויקטים מגוונים ומאתגרים', 'תנאים הוגנים ויציבות', 'אפשרויות קידום והתפתחות']::text[], true, '{"en":{"title":"Engineers & Architects","subtitle":"Planning and engineering at the highest level","intro":"Engineer and architect for planning, managing and supervising residential, commercial and public projects.","req":["Degree in civil engineering / architecture","Listed in the Register of Engineers and Architects","At least 2 years of experience","Proficiency in AutoCAD and Revit"],"adv":["Experience submitting building permits","Experience in on-site design supervision"],"offer":["Working in a professional, family-run group","Diverse and challenging projects","Fair conditions and stability","Opportunities for promotion and growth"]},"ru":{"title":"Инженеры и архитекторы","subtitle":"Проектирование и инженерия высочайшего уровня","intro":"Инженер и архитектор для проектирования, сопровождения и надзора за жилыми, коммерческими и общественными проектами.","req":["Диплом инженера-строителя / архитектора","Регистрация в реестре инженеров и архитекторов","Опыт работы не менее 2 лет","Владение AutoCAD и Revit"],"adv":["Опыт подачи заявок на разрешение на строительство","Опыт авторского надзора на объекте"],"offer":["Работа в семейной и профессиональной группе","Разнообразные и интересные проекты","Честные условия и стабильность","Возможности карьерного роста и развития"]},"fr":{"title":"Ingénieurs et architectes","subtitle":"Conception et ingénierie au plus haut niveau","intro":"Ingénieur et architecte pour la conception, le suivi et la supervision de projets résidentiels, commerciaux et publics.","req":["Diplôme en génie civil / architecture","Inscription au registre des ingénieurs et architectes","Au moins 2 ans d’expérience","Maîtrise d’AutoCAD et de Revit"],"adv":["Expérience dans le dépôt de permis de construire","Expérience en supervision de chantier"],"offer":["Travailler au sein d’un groupe familial et professionnel","Des projets variés et stimulants","Des conditions équitables et de la stabilité","Des possibilités d’évolution et de développement"]}}'::jsonb, 'published', 3),
  ('r2', 'קבלני משנה ובעלי מקצוע', 'בעלי מקצוע מנוסים לעבודה משותפת לאורך זמן', 'מחפשים קבלני משנה ובעלי מקצוע לשיתוף פעולה לאורך זמן בפרויקטים של הקבוצה.', array['רישיון / הסמכה בתחום המקצועי', 'ניסיון מוכח ותיק עבודות', 'עבודה לפי תקנים ולוחות זמנים', 'ביטוח צד ג'' ואחריות מקצועית בתוקף']::text[], array['צוות עובדים קבוע', 'ניסיון בעבודה מול חברות בנייה גדולות']::text[], array['עבודה בקבוצה משפחתית ומקצועית', 'פרויקטים מגוונים ומאתגרים', 'תנאים הוגנים ויציבות', 'אפשרויות קידום והתפתחות']::text[], true, '{"en":{"title":"Subcontractors & Tradespeople","subtitle":"Experienced professionals for long-term cooperation","intro":"We are looking for subcontractors and tradespeople for long-term cooperation on the group’s projects.","req":["Licence / certification in your trade","Proven experience and a portfolio of work","Working to standards and schedules","Valid third-party and professional liability insurance"],"adv":["A permanent team of workers","Experience working with large construction companies"],"offer":["Working in a professional, family-run group","Diverse and challenging projects","Fair conditions and stability","Opportunities for promotion and growth"]},"ru":{"title":"Субподрядчики и мастера","subtitle":"Опытные мастера для долгосрочного сотрудничества","intro":"Ищем субподрядчиков и мастеров для долгосрочного сотрудничества в проектах группы.","req":["Лицензия / сертификат по специальности","Подтверждённый опыт и портфолио работ","Работа по стандартам и в срок","Действующая страховка гражданской и профессиональной ответственности"],"adv":["Постоянная бригада","Опыт работы с крупными строительными компаниями"],"offer":["Работа в семейной и профессиональной группе","Разнообразные и интересные проекты","Честные условия и стабильность","Возможности карьерного роста и развития"]},"fr":{"title":"Sous-traitants et artisans","subtitle":"Des professionnels expérimentés pour une collaboration durable","intro":"Nous recherchons des sous-traitants et des artisans pour une collaboration durable sur les projets du groupe.","req":["Licence / certification dans votre métier","Expérience prouvée et portfolio de réalisations","Respect des normes et des délais","Assurance responsabilité civile et professionnelle en cours de validité"],"adv":["Une équipe de travail permanente","Expérience avec de grandes entreprises de construction"],"offer":["Travailler au sein d’un groupe familial et professionnel","Des projets variés et stimulants","Des conditions équitables et de la stabilité","Des possibilités d’évolution et de développement"]}}'::jsonb, 'published', 4)
